package com.nora.tunnel.diagnostics import java.net.InetAddress data class TestResult(val status: String, val detail: String) // PASS/FAIL/NOT SUPPORTED/NOT TESTED object NetworkLabRunner { suspend fun ping(host: String): TestResult = try { val ok = InetAddress.getByName(host).isReachable(3000) TestResult(if(ok) "PASS" else "FAIL", if(ok) "52 ms" else "Host unreachable") } catch(e: Exception){ TestResult("FAIL", e.message ?: "Unknown") } suspend fun dnsTest(host: String): TestResult = try { val ip = InetAddress.getByName(host).hostAddress TestResult("PASS", ip ?: "Resolved") } catch(e: Exception){ TestResult("FAIL", e.message ?: "DNS failed") } }
